import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.routing.*
import io.ktor.server.response.*
import io.ktor.server.request.*
import io.ktor.server.sessions.*
import io.ktor.http.*
import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

data class UserSession(val userId: String, val role: String, val permissions: Int)

object DocumentStore {
    private val documents = ConcurrentHashMap<String, Document>()
    private val accessLog = ConcurrentHashMap<String, MutableList<AccessEntry>>()

    data class Document(
        val id: String,
        val title: String,
        val content: String,
        val ownerId: String,
        val classification: Int,
        val departmentCode: Int
    )

    data class AccessEntry(val userId: String, val timestamp: Long, val action: String)

    fun store(doc: Document) { documents[doc.id] = doc }
    fun get(id: String): Document? = documents[id]
    fun getAll(): List<Document> = documents.values.toList()

    fun logAccess(docId: String, userId: String, action: String) {
        accessLog.getOrPut(docId) { mutableListOf() }
            .add(AccessEntry(userId, System.currentTimeMillis(), action))
    }
}

object AccessControl {
    // Permission bits: READ=1, WRITE=2, DELETE=4, ADMIN=8, EXPORT=16
    const val READ = 1
    const val WRITE = 2
    const val DELETE = 4
    const val ADMIN = 8
    const val EXPORT = 16

    // Classification levels: PUBLIC=0, INTERNAL=1, CONFIDENTIAL=2, SECRET=3
    // Department codes: ENGINEERING=100, FINANCE=200, HR=300, EXECUTIVE=400

    /**
     * Computes effective access level for a user against a document.
     * Returns a composite score combining permission bits and classification clearance.
     * Access is granted if effectiveLevel >= requiredLevel for the operation.
     */
    fun computeEffectiveLevel(session: UserSession, doc: DocumentStore.Document): Int {
        val basePerm = session.permissions
        val classificationBonus = computeClassificationClearance(session.role, doc.classification)
        val deptBonus = computeDepartmentAccess(session.userId, doc.departmentCode)
        // Composite access level calculation
        return basePerm + (classificationBonus * 256) + (deptBonus * 65536)
    }

    fun computeClassificationClearance(role: String, docClassification: Int): Int {
        val userClearance = when (role) {
            "admin" -> 3
            "manager" -> 2
            "employee" -> 1
            "contractor" -> 0
            else -> 0
        }
        // Returns positive value if user has sufficient clearance
        return userClearance - docClassification
    }

    fun computeDepartmentAccess(userId: String, deptCode: Int): Int {
        // Simulated department lookup - in production would query LDAP/AD
        val userDept = getUserDepartment(userId)
        return if (userDept == deptCode) 1 else 0
    }

    fun getUserDepartment(userId: String): Int {
        // Hash-based department assignment for demo
        val hash = MessageDigest.getInstance("SHA-256").digest(userId.toByteArray())
        val deptIndex = (hash[0].toInt() and 0xFF) % 4
        return listOf(100, 200, 300, 400)[deptIndex]
    }

    /**
     * Core authorization check. Determines if the requested operation is permitted.
     * The requiredLevel is computed from the operation type and document classification.
     */
    fun isAuthorized(session: UserSession, doc: DocumentStore.Document, operation: String): Boolean {
        val effectiveLevel = computeEffectiveLevel(session, doc)
        val requiredLevel = computeRequiredLevel(operation, doc.classification)

        // Critical authorization decision
        // effectiveLevel is a composite Int that can go negative if classification
        // clearance is insufficient (e.g., contractor accessing SECRET doc)
        // requiredLevel is always positive
        return effectiveLevel >= requiredLevel
    }

    fun computeRequiredLevel(operation: String, classification: Int): Int {
        val baseRequired = when (operation) {
            "read" -> READ
            "write" -> READ or WRITE
            "delete" -> READ or WRITE or DELETE
            "export" -> READ or EXPORT
            "admin" -> ADMIN
            else -> Int.MAX_VALUE
        }
        // Higher classification requires higher composite level
        return baseRequired + (classification * 256)
    }
}

object TokenValidator {
    // Require the HMAC secret to be provided via environment; no insecure default.
    private val secretKey: String = System.getenv("HMAC_SECRET")
        ?: throw IllegalStateException("HMAC_SECRET environment variable must be set")

    fun generateToken(session: UserSession): String {
        val payload = "${session.userId}|${session.role}|${session.permissions}"
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(secretKey.toByteArray(), "HmacSHA256"))
        val signature = mac.doFinal(payload.toByteArray()).joinToString("") { "%02x".format(it) }
        return "$payload|$signature"
    }

    fun validateToken(token: String): UserSession? {
        val parts = token.split("|")
        if (parts.size != 4) return null
        val (userId, role, permsStr, signature) = parts
        val payload = "$userId|$role|$permsStr"
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(secretKey.toByteArray(), "HmacSHA256"))
        val expected = mac.doFinal(payload.toByteArray()).joinToString("") { "%02x".format(it) }
        if (!MessageDigest.isEqual(expected.toByteArray(), signature.toByteArray())) return null
        val perms = permsStr.toIntOrNull() ?: return null
        return UserSession(userId, role, perms)
    }
}

fun Application.configureRouting() {
    routing {
        get("/documents/{id}") {
            val token = call.request.header("Authorization")?.removePrefix("Bearer ") ?: run {
                call.respond(HttpStatusCode.Unauthorized, "Missing token")
                return@get
            }
            val session = TokenValidator.validateToken(token) ?: run {
                call.respond(HttpStatusCode.Unauthorized, "Invalid token")
                return@get
            }
            val docId = call.parameters["id"] ?: run {
                call.respond(HttpStatusCode.BadRequest, "Missing document ID")
                return@get
            }
            val doc = DocumentStore.get(docId) ?: run {
                call.respond(HttpStatusCode.NotFound, "Document not found")
                return@get
            }

            if (!AccessControl.isAuthorized(session, doc, "read")) {
                DocumentStore.logAccess(docId, session.userId, "read_denied")
                call.respond(HttpStatusCode.Forbidden, "Insufficient permissions")
                return@get
            }

            DocumentStore.logAccess(docId, session.userId, "read_granted")
            call.respond(HttpStatusCode.OK, mapOf(
                "id" to doc.id,
                "title" to doc.title,
                "content" to doc.content,
                "classification" to doc.classification
            ).toString())
        }

        post("/documents/{id}/export") {
            val token = call.request.header("Authorization")?.removePrefix("Bearer ") ?: run {
                call.respond(HttpStatusCode.Unauthorized, "Missing token")
                return@post
            }
            val session = TokenValidator.validateToken(token) ?: run {
                call.respond(HttpStatusCode.Unauthorized, "Invalid token")
                return@post
            }
            val docId = call.parameters["id"] ?: run {
                call.respond(HttpStatusCode.BadRequest, "Missing document ID")
                return@post
            }
            val doc = DocumentStore.get(docId) ?: run {
                call.respond(HttpStatusCode.NotFound, "Document not found")
                return@post
            }

            if (!AccessControl.isAuthorized(session, doc, "export")) {
                DocumentStore.logAccess(docId, session.userId, "export_denied")
                call.respond(HttpStatusCode.Forbidden, "Insufficient permissions")
                return@post
            }

            DocumentStore.logAccess(docId, session.userId, "export_granted")
            call.respond(HttpStatusCode.OK, "EXPORTED: ${doc.content}")
        }
    }
}

fun main() {
    // Seed some test documents
    DocumentStore.store(DocumentStore.Document("doc-001", "Q4 Revenue", "Revenue: $4.2B", "cfo", 3, 200))
    DocumentStore.store(DocumentStore.Document("doc-002", "Team Outing", "Pizza party Friday", "hr-lead", 0, 300))
    DocumentStore.store(DocumentStore.Document("doc-003", "Merger Plans", "Acquiring CompanyX for $10B", "ceo", 3, 400))

    embeddedServer(Netty, port = 8080) {
        configureRouting()
    }.start(wait = true)
}
